package org.joni;

/** Provenance for the upper edge of Perl's signed executable scalar domain. */
public enum WideScalarDomainEnd {
    /** The finite, executable signed-IV ceiling ({@link Long#MAX_VALUE}). */
    HIGHEST_SCALAR,
    /** Perl's symbolic UV_MAX class endpoint; never an executable scalar. */
    PERL_INFINITY
}
